  static IEnumerable<Expander> FindExpanders(DependencyObject root){for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++){var child=System.Windows.Media.VisualTreeHelper.GetChild(root,i);var exp=child as Expander;if(exp!=null)yield return exp;foreach(var e in FindExpanders(child))yield return e;}}
  void BuildRainPage(string module){Find<TextBlock>("PageSubtitle").Text="雨课堂 · 当前账号独立任务、媒体进度与题目处理。";rainTasks=null;if(module=="signin"){var p=Column();p.Children.Add(Text("雨课堂签到",22,"#293B58"));p.Children.Add(Text("雨课堂签到接口尚未通过真实账号验证。当前保留平台入口供人工签到，自动普通签到仅适用于学习通。",14,"#78869B"));p.Children.Add(Button("打开当前账号平台窗口",async()=>await RainRequest("/login",null),false));content.Children.Add(Card(p));return;}var connection=Column();connection.Children.Add(Text("雨课堂账号与课程",20,"#293B58"));connection.Children.Add(Text("首次使用：右上角切换账号 → 添加账号空间 → 打开登录窗口 → 完成平台登录 → 确认已登录。登录信息保存在此账号独立目录。",13,"#78869B"));var login=new WrapPanel();login.Children.Add(Button("打开登录 / 平台窗口",async()=>await RainRequest("/login",null),false));login.Children.Add(Button("确认已登录",async()=>{await RainRequest("/login/confirm",null);await LoadWorkspace();},true));login.Children.Add(Button("读取当前页面课程",async()=>await LoadRainCourses(),true));connection.Children.Add(login);content.Children.Add(Card(connection));var add=Column();add.Children.Add(Text("添加"+(module=="chapters"?"章节课程":module=="homework"?"作业":"考试")+"任务",18,"#293B58"));add.Children.Add(Text("选择可读取的课程链接，或在独立平台窗口进入对应课程后使用当前地址。也可直接粘贴课程、作业或考试页面地址。",13,"#78869B"));rainCourses=new ComboBox{DisplayMemberPath="Title",MinHeight=36};rainCourses.SelectionChanged+=(s,e)=>{var c=rainCourses.SelectedItem as CourseItem;if(c!=null){rainTitle.Text=c.Title;rainUrl.Text=Data.Text(c.Value,"url");}};add.Children.Add(rainCourses);add.Children.Add(Text("名称",12,"#78869B"));rainTitle=new TextBox();add.Children.Add(rainTitle);add.Children.Add(Text("雨课堂页面地址（HTTPS）",12,"#78869B"));rainUrl=new TextBox();add.Children.Add(rainUrl);var buttons=new WrapPanel();buttons.Children.Add(Button("使用当前课程 / 题目地址",async()=>{try{var r=await client.RequestAsync("/local/yuketang/current",null,lifetime.Token);var d=Data.Map(r,"data");rainTitle.Text=Data.Text(d,"title");rainUrl.Text=Data.Text(d,"url");}catch(Exception e){Message(Friendly(e));}},true));buttons.Children.Add(Button("添加任务",async()=>{try{var r=awa