  async Task RainRequest(string path,Dictionary<string,object> body){if(actionBusy)return;actionBusy=true;try{var r=await Write("/local/yuketang"+path,body??new Dictionary<string,object>());Message(Data.Text(r,"msg"));}catch(Exception e){Message(Friendly(e));}finally{actionBusy=false;}}
  async Task LoadRainCourses(){try{var r=await client.RequestAsync("/local/yuketang/courses",null,lifetime.Token);var d=Data.Map(r,"data");rainCourses.Items.Clear();foreach(var c in Data.Rows(d,"courses"))rainCourses.Items.Add(new CourseItem{Title=Data.Text(c,"title"),Value=c});Message(Data.Text(d,"message"));}catch(Exception e){Message(Friendly(e));}}
  static string RainState(string s){return s=="completed"?"已完成":s=="running"?"进行中":s=="starting"?"正在启动":s=="verification"?"等待安全验证":s=="ready"?"等待确认提交":s=="manual"?"需要核对":s=="failed"?"执行异常":"已停止";}
  async Task LoadRainTasks(){if(!ready||platform!="yuketang"||rainLoading||rainTasks==null)return;rainLoading=true;int version=scopeVersion;string module=page;try{var r=await client.RequestAsync("/local/yuketang/tasks?module="+module,null,lifetime.Token);if(version!=scopeVersion||page!=module||platform!="yuketang"||rainTasks==null)return;var d=Data.Map(r,"data");rainTasks.Children.Clear();int count=0;foreach(var t in Data.Rows(d,"items")){count++;rainTasks.Children.Add(RainTaskCard(t));}if(count==0)rainTasks.Children.Add(Card(Text("当前雨课堂账号暂无此类任务。添加任务后会在这里显示。",15,"#78869B")));Message(Data.Text(d,"message"));}catch(Exception e){if(version==scopeVersion)Message(Friendly(e));}finally{rainLoading=false;}}
  UIElement RainTaskCard(Dictionary<string,object> t){string id=Data.Text(t,"id"),state=Data.Text(t,"state");var p=Column();p.Children.Add(Text(Data.Text(t,"title")+" · "+RainState(state),19,"#293B58"));double duration=Data.Number(t,"duration"),position=Data.Number(t,"position");if(duration>0){p.Children.Add(Text("当前媒体  "+Time(position)+" / "+Time(duration),14,"#5274A8"));p.Children.Add(new ProgressBar{Maximum=100,Value=Math.Min(100,position/duration*100)});}if(Data.Number(t,"questionTotal")>0)p.Children.Add(Text("当前第 "+Data.Text(t,"questionIndex")+" / "+Data.Text(t,"questionTotal")+" 题",14,"#5274A8"));p.Children.Add(Text(Data.Text(t,"message"),13,"#78869B"));var actions=new WrapPanel();bool running=new[]{"starting","running","verification","ready","manual"}.Contains(state);if(!running)actions.Children.Add(Button("开始任务",async()=>await StartRain(t),false));if(running)actions.Children.Add(Button("停止任务",async()=>await RainTaskAction(id,"stop"),true));if(state=="ready")actions.Children.Add(Button("确认提交已准备答案",async()=>{if(Confirm("向雨课堂提交已准备的答案？若当前是交卷入口，将结束本次作业或考试。"))await RainTaskAction(id,"submit");},false));if(!running)actions.Children.Add(Button("删除任务",async()=>{if(Confirm("删除此雨课堂任务？已收录复习资料保留。"))await RainTaskAction(id,"delete");},true));actions.Children.Add(Button("收录当前页面题目",async()=>{await RainRequest("/review/collect",new Dictionary<string,object>{{"course",id}});},true));p.Children.Add(actions);return Card(p);}
