  async Task StartRain(Dictionary<string,object> t){var dialog=new Window{Owner=window,Title="开始雨课堂任务",Width=570,Height=350,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=Color("#F3F5FA"),Resources=window.Resources};var p=new StackPanel{Margin=new Thickness(25)};p.Children.Add(Text(Data.Text(t,"title"),20,"#293B58"));p.Children.Add(Text("自动答题使用设置中的DeepSeek，可能产生API费用。正式考试进入后可能开始计时，请先确认平台安排。",14,"#78869B"));var ai=new CheckBox{Content="启用AI参考答题",IsChecked=false,Margin=new Thickness(0,10,0,8)};var submit=new CheckBox{Content="自动提交已准备的题目答案",IsChecked=false,Margin=new Thickness(0,0,0,12)};p.Children.Add(ai);p.Children.Add(submit);p.Children.Add(Button("确认开始",()=>dialog.DialogResult=true,false));dialog.Content=p;if(dialog.ShowDialog()!=true)return;await RainRequest("/tasks/start",new Dictionary<string,object>{{"id",Data.Text(t,"id")},{"autoAI",ai.IsChecked==true},{"autoSubmit",submit.IsChecked==true},{"confirmed",true}});await LoadRainTasks();}
